<?php

namespace App\Console\Commands;
use Illuminate\Console\Command;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Redis;
class PublishOutboxEvents extends Command{protected $signature='celeone:outbox:publish {--once} {--limit=100}';protected $description='Publish committed PostgreSQL outbox events to the realtime gateway.';public function handle():int{do{$rows=DB::table('outbox_events')->whereNull('published_at')->orderBy('created_at')->limit(min(500,max(1,(int)$this->option('limit'))))->get();foreach($rows as $row){try{Redis::publish('celeone:outbox',json_encode(['event_id'=>$row->id,'event'=>$row->event_type,'aggregate_type'=>$row->aggregate_type,'aggregate_id'=>$row->aggregate_id,'occurred_at'=>$row->created_at,'version'=>1,'data'=>json_decode($row->payload,true)],JSON_THROW_ON_ERROR));DB::table('outbox_events')->where('id',$row->id)->update(['published_at'=>now(),'attempts'=>DB::raw('attempts + 1'),'updated_at'=>now()]);}catch(\Throwable $e){DB::table('outbox_events')->where('id',$row->id)->update(['attempts'=>DB::raw('attempts + 1'),'last_error'=>$e->getMessage(),'updated_at'=>now()]);$this->error($e->getMessage());}}if($this->option('once'))break;if($rows->isEmpty())usleep(500000);}while(true);return self::SUCCESS;}}
